"""Offline synthetic QUIC v1 trace auditor.

Reads one JSON document from stdin, writes one JSON document to stdout.
See the task contract for the authoritative protocol semantics.
"""
import sys
import json
import re
import bisect

MAXP = 4611686018427387903
BLOCK = 128
BMASK = (1 << BLOCK) - 1
LEVELS = ('I', 'H', 'Z', 'A')
CFG_KEYS = ('early', 'overlap', 'buffer_packets', 'idle_ms', 'max_streams_bidi',
            'max_streams_uni', 'max_stream_data', 'max_data', 'crypto_limit', 'sent')

ID_RE = re.compile(r'\A[A-Za-z0-9_-]{1,32}\Z')
HEX_RE = re.compile(r'\A(?:[0-9a-f]{2})*\Z')

FRAME_KEYS = {
    'PADDING': (),
    'PING': (),
    'HANDSHAKE_DONE': (),
    'UNKNOWN': (),
    'ACK': ('ranges',),
    'CRYPTO': ('offset', 'data_hex'),
    'STREAM': ('id', 'offset', 'data_hex', 'fin'),
    'RESET_STREAM': ('id', 'final_size'),
    'STOP_SENDING': ('id',),
    'CLOSE': ('app', 'code'),
}

# status / reasons
S_DROP = 'dropped'
S_OK = 'accepted'
S_DUP = 'duplicate'
S_ERR = 'error'
S_BUF = 'buffered'


class Invalid(Exception):
    pass


class Err(Exception):
    """Semantic frame error; frame index is attached by the packet loop."""
    __slots__ = ('code', 'frame')

    def __init__(self, code):
        self.code = code
        self.frame = None


def die():
    raise Invalid()


def is_int(v):
    return type(v) is int


def req_int(v, lo, hi):
    if type(v) is not int or v < lo or v > hi:
        die()
    return v


def keys_exact(d, names):
    if len(d) != len(names):
        die()
    for n in names:
        if n not in d:
            die()


# --------------------------------------------------------------------------
# parsing / validation
# --------------------------------------------------------------------------

def parse_text(data):
    try:
        text = data.decode('utf-8')
    except Exception:
        die()

    def hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                die()
            d[k] = v
        return d

    def const(name):
        die()

    try:
        return json.loads(text, object_pairs_hook=hook, parse_constant=const)
    except Invalid:
        raise
    except Exception:
        die()


def check_ranges_config(rs):
    if type(rs) is not list or len(rs) > 32:
        die()
    prev = None
    for r in rs:
        if type(r) is not list or len(r) != 2:
            die()
        lo, hi = r
        if type(lo) is not int or type(hi) is not int:
            die()
        if lo < 0 or hi > MAXP or lo > hi:
            die()
        if prev is not None and lo <= prev + 1:
            die()
        prev = hi


def check_hex(s):
    if type(s) is not str or len(s) > 4096 or not HEX_RE.match(s):
        die()


def check_ack_ranges(rs):
    if type(rs) is not list or len(rs) > 32:
        die()
    for r in rs:
        if type(r) is not list or len(r) != 2:
            die()
        req_int(r[0], 0, MAXP)
        req_int(r[1], 0, MAXP)


def validate_frame(f):
    if type(f) is not dict:
        die()
    ft = f.get('type')
    if type(ft) is not str:
        die()
    extra = FRAME_KEYS.get(ft)
    if extra is None:
        die()
    keys_exact(f, ('type',) + extra)
    if ft == 'ACK':
        check_ack_ranges(f['ranges'])
    elif ft == 'CRYPTO':
        req_int(f['offset'], 0, MAXP)
        check_hex(f['data_hex'])
        f['_d'] = bytes.fromhex(f['data_hex'])
    elif ft == 'STREAM':
        req_int(f['id'], 0, MAXP)
        req_int(f['offset'], 0, MAXP)
        check_hex(f['data_hex'])
        if type(f['fin']) is not bool:
            die()
        f['_d'] = bytes.fromhex(f['data_hex'])
    elif ft == 'RESET_STREAM':
        req_int(f['id'], 0, MAXP)
        req_int(f['final_size'], 0, MAXP)
    elif ft == 'STOP_SENDING':
        req_int(f['id'], 0, MAXP)
    elif ft == 'CLOSE':
        if type(f['app']) is not bool:
            die()
        req_int(f['code'], 0, MAXP)


def validate(obj):
    if type(obj) is not dict:
        die()
    keys_exact(obj, ('version', 'traces'))
    if type(obj['version']) is not int or obj['version'] != 1:
        die()
    traces = obj['traces']
    if type(traces) is not list or len(traces) > 32:
        die()
    cnt = [0, 0, 0, 0]  # events, packets, frames, data bytes
    ids = set()
    for tr in traces:
        if type(tr) is not dict:
            die()
        keys_exact(tr, ('id', 'config', 'events'))
        tid = tr['id']
        if type(tid) is not str or not ID_RE.match(tid):
            die()
        if tid in ids:
            die()
        ids.add(tid)
        cfg = tr['config']
        if type(cfg) is not dict:
            die()
        keys_exact(cfg, CFG_KEYS)
        if type(cfg['early']) is not bool:
            die()
        if cfg['overlap'] not in ('reject', 'first'):
            die()
        req_int(cfg['buffer_packets'], 0, 1024)
        req_int(cfg['idle_ms'], 0, 1000000000)
        req_int(cfg['max_streams_bidi'], 0, 1024)
        req_int(cfg['max_streams_uni'], 0, 1024)
        req_int(cfg['max_stream_data'], 0, 65536)
        req_int(cfg['max_data'], 0, MAXP)
        req_int(cfg['crypto_limit'], 0, 65536)
        sent = cfg['sent']
        if type(sent) is not dict:
            die()
        keys_exact(sent, ('I', 'H', 'A'))
        for lv in LEVELS_S:
            check_ranges_config(sent[lv])
        events = tr['events']
        if type(events) is not list:
            die()
        cnt[0] += len(events)
        if cnt[0] > 20000:
            die()
        last_t = None
        for ev in events:
            if type(ev) is not dict:
                die()
            t = ev.get('t')
            if type(t) is not int or t < 0 or t > 1000000000000:
                die()
            if last_t is not None and t < last_t:
                die()
            last_t = t
            op = ev.get('op')
            if op == 'key':
                keys_exact(ev, ('t', 'op', 'level', 'action'))
                if ev['level'] not in LEVELS_S or ev['action'] not in ('install', 'discard'):
                    die()
            elif op == 'tick':
                keys_exact(ev, ('t', 'op'))
            elif op == 'datagram':
                keys_exact(ev, ('t', 'op', 'bytes', 'packets'))
                req_int(ev['bytes'], 0, 65535)
                pkts = ev['packets']
                if type(pkts) is not list or not (1 <= len(pkts) <= 16):
                    die()
                cnt[1] += len(pkts)
                if cnt[1] > 20000:
                    die()
                for pkt in pkts:
                    if type(pkt) is not dict:
                        die()
                    keys_exact(pkt, ('level', 'pn', 'auth', 'frames'))
                    if pkt['level'] not in LEVELS_S:
                        die()
                    req_int(pkt['pn'], 0, MAXP)
                    if type(pkt['auth']) is not bool:
                        die()
                    frames = pkt['frames']
                    if type(frames) is not list or len(frames) > 64:
                        die()
                    cnt[2] += len(frames)
                    if cnt[2] > 60000:
                        die()
                    for f in frames:
                        validate_frame(f)
                        if f['type'] == 'CRYPTO' or f['type'] == 'STREAM':
                            cnt[3] += len(f['_d'])
            else:
                die()
    if cnt[3] > 2 * 1024 * 1024:
        die()
    return traces


LEVELS_S = ('I', 'H', 'Z', 'A')


# --------------------------------------------------------------------------
# byte reassembly store
# --------------------------------------------------------------------------

class Store:
    """Sparse byte store keyed by fixed-size blocks.

    Each block is a [bytearray(BLOCK), present_mask] pair.
    """
    __slots__ = ('blocks',)

    def __init__(self):
        self.blocks = {}

    def conflicts(self, off, data):
        n = len(data)
        if n == 0:
            return False
        end = off + n
        first = off // BLOCK
        last = (end - 1) // BLOCK
        blocks = self.blocks
        for bi in range(first, last + 1):
            b = blocks.get(bi)
            if b is None:
                continue
            bstart = bi * BLOCK
            buf, mask = b
            lo = off - bstart
            if lo < 0:
                lo = 0
            hi = end - bstart
            if hi > BLOCK:
                hi = BLOCK
            m = (mask >> lo) & ((1 << (hi - lo)) - 1)
            base = bstart + lo - off  # index into data of block position lo
            while m:
                lsb = m & -m
                s = lsb.bit_length() - 1
                y = m + lsb
                run = m & (y - 1)
                k = run.bit_count()
                if buf[lo + s:lo + s + k] != data[base + s:base + s + k]:
                    return True
                m ^= run
        return False

    def store(self, off, data, j, keep_existing):
        n = len(data)
        if n == 0:
            return
        end = off + n
        first = off // BLOCK
        last = (end - 1) // BLOCK
        blocks = self.blocks
        for bi in range(first, last + 1):
            bstart = bi * BLOCK
            lo = off - bstart
            if lo < 0:
                lo = 0
            hi = end - bstart
            if hi > BLOCK:
                hi = BLOCK
            b = blocks.get(bi)
            if b is None:
                j.snap_block(self, bi, None, 0)
                b = [bytearray(BLOCK), 0]
                blocks[bi] = b
            else:
                j.snap_block(self, bi, b[0], b[1])
            buf = b[0]
            mask = b[1]
            if keep_existing:
                free = ((1 << (hi - lo)) - 1) & ~(mask >> lo)
                base = bstart + lo - off
                while free:
                    lsb = free & -free
                    s = lsb.bit_length() - 1
                    y = free + lsb
                    run = free & (y - 1)
                    k = run.bit_count()
                    buf[lo + s:lo + s + k] = data[base + s:base + s + k]
                    mask |= run << lo
                    free ^= run
            else:
                buf[lo:hi] = data[bstart + lo - off:bstart + hi - off]
                mask |= ((1 << (hi - lo)) - 1) << lo
            b[1] = mask

    def prefix(self):
        out = bytearray()
        bi = 0
        blocks = self.blocks
        while True:
            b = blocks.get(bi)
            if b is None:
                break
            buf, mask = b
            fz = ~mask & BMASK
            if fz:
                fz = (fz & -fz).bit_length() - 1
            else:
                fz = BLOCK
            out += buf[:fz]
            if fz < BLOCK:
                break
            bi += 1
        return bytes(out)


class Journal:
    __slots__ = ('items', 'seen', 'st')

    def __init__(self, st):
        self.items = []
        self.seen = set()
        self.st = st

    def snap_block(self, store, bi, data, mask):
        key = (store, bi)
        if key in self.seen:
            return
        self.seen.add(key)
        self.items.append((0, store, bi, data, mask))

    def snap_stream(self, s):
        if s in self.seen:
            return
        self.seen.add(s)
        self.items.append((1, s, s.highest, s.final_size, s.reset, s.stopped))

    def snap_total(self):
        if 'T' in self.seen:
            return
        self.seen.add('T')
        self.items.append((2, self.st.received_total))

    def new_stream(self, sid):
        self.items.append((3, sid))

    def rollback(self):
        st = self.st
        for it in reversed(self.items):
            k = it[0]
            if k == 0:
                store = it[1]
                bi = it[2]
                data = it[3]
                if data is None:
                    store.blocks.pop(bi, None)
                else:
                    b = store.blocks.get(bi)
                    if b is None:
                        store.blocks[bi] = [bytearray(data), it[4]]
                    else:
                        b[0][:] = data
                        b[1] = it[4]
            elif k == 1:
                s = it[1]
                s.highest = it[2]
                s.final_size = it[3]
                s.reset = it[4]
                s.stopped = it[5]
            elif k == 2:
                st.received_total = it[1]
            else:
                st.streams.pop(it[1], None)


class Stream:
    __slots__ = ('sid', 'highest', 'final_size', 'reset', 'stopped', 'store')

    def __init__(self, sid):
        self.sid = sid
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False
        self.store = Store()


def permitted(level, f):
    ft = f['type']
    if ft == 'PADDING' or ft == 'PING':
        return True
    if ft == 'ACK' or ft == 'CRYPTO':
        return level != 'Z'
    if ft == 'STREAM' or ft == 'RESET_STREAM' or ft == 'STOP_SENDING':
        return level == 'Z' or level == 'A'
    if ft == 'CLOSE':
        if f['app']:
            return level == 'Z' or level == 'A'
        return True
    return False


def covered(lows, sent, lo, hi):
    i = bisect.bisect_right(lows, lo) - 1
    return i >= 0 and sent[i][1] >= hi


class State:
    __slots__ = ('early', 'overlap', 'buffer_packets', 'idle_ms', 'max_streams_bidi',
                 'max_streams_uni', 'max_stream_data', 'max_data', 'crypto_limit',
                 'sent', 'sent_lows', 'keys', 'pnsets', 'streams', 'crypto',
                 'crypto_high', 'received_total', 'pending', 'last_activity',
                 'term', 'term_at', 'results')

    def __init__(self, cfg):
        self.early = cfg['early']
        self.overlap = cfg['overlap']
        self.buffer_packets = cfg['buffer_packets']
        self.idle_ms = cfg['idle_ms']
        self.max_streams_bidi = cfg['max_streams_bidi']
        self.max_streams_uni = cfg['max_streams_uni']
        self.max_stream_data = cfg['max_stream_data']
        self.max_data = cfg['max_data']
        self.crypto_limit = cfg['crypto_limit']
        sent = {}
        lows = {}
        for lv in ('I', 'H', 'A'):
            rs = [(r[0], r[1]) for r in cfg['sent'][lv]]
            sent[lv] = rs
            lows[lv] = [r[0] for r in rs]
        self.sent = sent
        self.sent_lows = lows
        self.keys = {'I': 'live', 'H': 'absent', 'Z': 'live' if self.early else 'absent',
                     'A': 'absent'}
        self.pnsets = {'I': set(), 'H': set(), 'A': set()}
        self.streams = {}
        self.crypto = {'I': Store(), 'H': Store(), 'A': Store()}
        self.crypto_high = {'I': 0, 'H': 0, 'A': 0}
        self.received_total = 0
        self.pending = []
        self.last_activity = 0
        self.term = None
        self.term_at = 0
        self.results = {}

    # -- bookkeeping ------------------------------------------------------

    def record(self, e, p, status, reason, at, frame):
        self.results[(e, p)] = (status, reason, at, frame)

    def terminate(self, state, code, at, source, peer_code):
        self.term = (state, code, at, source, peer_code)
        self.term_at = at
        if self.pending:
            for r in self.pending:
                self.record(r[0], r[1], S_DROP, 'CONNECTION_CLOSED', at, None)
            self.pending = []

    def fail(self, e, p, t, code, frame):
        self.terminate('closed', code, t, (e, p, frame), None)
        self.record(e, p, S_ERR, code, t, frame)

    def get_stream(self, sid, j):
        s = self.streams.get(sid)
        if s is None:
            s = Stream(sid)
            self.streams[sid] = s
            j.new_stream(sid)
        j.snap_stream(s)
        return s

    # -- events -----------------------------------------------------------

    def key_event(self, e, ev, t):
        level = ev['level']
        action = ev['action']
        cur = self.keys[level]
        if action == 'discard':
            if cur != 'discarded':
                self.keys[level] = 'discarded'
                if self.pending:
                    keep = []
                    for r in self.pending:
                        if r[3] == level:
                            self.record(r[0], r[1], S_DROP, 'KEYS_DISCARDED', t, None)
                        else:
                            keep.append(r)
                    self.pending = keep
        else:
            if cur == 'absent':
                self.keys[level] = 'live'
                drain = []
                keep = []
                for r in self.pending:
                    if r[3] == level:
                        drain.append(r)
                    else:
                        keep.append(r)
                self.pending = keep
                for r in drain:
                    if self.term is not None:
                        self.record(r[0], r[1], S_DROP, 'CONNECTION_CLOSED', self.term_at, None)
                    else:
                        self.process(r[0], r[1], r[4], t)

    def datagram(self, e, ev, t):
        pkts = ev['packets']
        size = ev['bytes']
        bad = False
        for pkt in pkts[:-1]:
            if pkt['level'] == 'A':
                bad = True
                break
        if bad:
            for p in range(len(pkts)):
                self.record(e, p, S_DROP, 'LAYOUT', t, None)
            return
        for p in range(len(pkts)):
            pkt = pkts[p]
            if self.term is not None:
                self.record(e, p, S_DROP, 'CONNECTION_CLOSED', t, None)
                continue
            lvl = pkt['level']
            if lvl == 'I' and size < 1200:
                self.record(e, p, S_DROP, 'INITIAL_TOO_SMALL', t, None)
                continue
            if lvl == 'Z' and not self.early:
                self.record(e, p, S_DROP, 'EARLY_REJECTED', t, None)
                continue
            ks = self.keys[lvl]
            if ks == 'discarded':
                self.record(e, p, S_DROP, 'KEYS_DISCARDED', t, None)
                continue
            if ks == 'absent':
                if len(self.pending) < self.buffer_packets:
                    self.pending.append((e, p, t, lvl, pkt))
                else:
                    self.record(e, p, S_DROP, 'BUFFER_FULL', t, None)
                continue
            self.process(e, p, pkt, t)

    # -- packet -----------------------------------------------------------

    def process(self, e, p, pkt, t):
        lvl = pkt['level']
        pn = pkt['pn']
        if not pkt['auth']:
            self.record(e, p, S_DROP, 'AUTH', t, None)
            return
        key = 'A' if (lvl == 'Z' or lvl == 'A') else lvl
        if pn in self.pnsets[key]:
            self.record(e, p, S_DUP, 'DUPLICATE', t, None)
            return
        frames = pkt['frames']
        if not frames:
            self.fail(e, p, t, 'FRAME_ENCODING_ERROR', None)
            return
        for i in range(len(frames)):
            f = frames[i]
            if f['type'] == 'UNKNOWN':
                self.fail(e, p, t, 'FRAME_ENCODING_ERROR', i)
                return
            if not permitted(lvl, f):
                self.fail(e, p, t, 'PROTOCOL_VIOLATION', i)
                return
        j = Journal(self)
        try:
            for i in range(len(frames)):
                f = frames[i]
                ft = f['type']
                if ft == 'PADDING' or ft == 'PING':
                    continue
                if ft == 'ACK':
                    self.do_ack(lvl, f)
                elif ft == 'CRYPTO':
                    self.do_crypto(lvl, f, j)
                elif ft == 'STREAM':
                    self.do_stream(f, j)
                elif ft == 'RESET_STREAM':
                    self.do_reset(f, j)
                elif ft == 'STOP_SENDING':
                    self.do_stop(f, j)
                else:  # CLOSE
                    app = f['app']
                    code = 'PEER_APPLICATION_CLOSE' if app else 'PEER_TRANSPORT_CLOSE'
                    self.pnsets[key].add(pn)
                    self.last_activity = t
                    self.terminate('closed', code, t, (e, p, i), f['code'])
                    self.record(e, p, S_OK, 'OK', t, None)
                    return
        except Err as ex:
            j.rollback()
            self.fail(e, p, t, ex.code, ex.frame)
            return
        self.pnsets[key].add(pn)
        self.last_activity = t
        self.record(e, p, S_OK, 'OK', t, None)

    # -- frames -----------------------------------------------------------

    def do_ack(self, lvl, f):
        rs = f['ranges']
        if not rs:
            raise Err('FRAME_ENCODING_ERROR')
        prev = None
        for r in rs:
            lo = r[0]
            hi = r[1]
            if lo > hi:
                raise Err('FRAME_ENCODING_ERROR')
            if prev is not None and lo <= prev + 1:
                raise Err('FRAME_ENCODING_ERROR')
            prev = hi
        sent = self.sent[lvl]
        lows = self.sent_lows[lvl]
        for r in rs:
            if not covered(lows, sent, r[0], r[1]):
                raise Err('PROTOCOL_VIOLATION')

    def do_crypto(self, lvl, f, j):
        data = f['_d']
        off = f['offset']
        end = off + len(data)
        if end > MAXP:
            raise Err('FRAME_ENCODING_ERROR')
        if end > self.crypto_limit:
            raise Err('CRYPTO_BUFFER_EXCEEDED')
        st = self.crypto[lvl]
        if self.overlap == 'reject' and st.conflicts(off, data):
            raise Err('PROTOCOL_VIOLATION')
        st.store(off, data, j, self.overlap == 'first')
        if end > self.crypto_high[lvl]:
            self.crypto_high[lvl] = end

    def stream_limit(self, sid):
        m = sid & 3
        if m == 0:
            return self.max_streams_bidi
        if m == 2:
            return self.max_streams_uni
        return None

    def do_stream(self, f, j):
        sid = f['id']
        limit = self.stream_limit(sid)
        if limit is None:
            raise Err('STREAM_STATE_ERROR')
        if (sid >> 2) + 1 > limit:
            raise Err('STREAM_LIMIT_ERROR')
        s = self.get_stream(sid, j)
        data = f['_d']
        off = f['offset']
        fin = f['fin']
        end = off + len(data)
        if end > MAXP:
            raise Err('FRAME_ENCODING_ERROR')
        fs = s.final_size
        if fs is not None and (end > fs or (fin and end != fs)):
            raise Err('FINAL_SIZE_ERROR')
        if fin and end < s.highest:
            raise Err('FINAL_SIZE_ERROR')
        if end > self.max_stream_data:
            raise Err('FLOW_CONTROL_ERROR')
        nh = s.highest if s.highest > end else end
        if nh != s.highest and self.received_total + (nh - s.highest) > self.max_data:
            raise Err('FLOW_CONTROL_ERROR')
        if not s.reset:
            if self.overlap == 'reject' and s.store.conflicts(off, data):
                raise Err('PROTOCOL_VIOLATION')
            s.store.store(off, data, j, self.overlap == 'first')
        if nh != s.highest:
            j.snap_total()
            self.received_total += nh - s.highest
            s.highest = nh
        if fin:
            s.final_size = end

    def do_reset(self, f, j):
        sid = f['id']
        limit = self.stream_limit(sid)
        if limit is None:
            raise Err('STREAM_STATE_ERROR')
        if (sid >> 2) + 1 > limit:
            raise Err('STREAM_LIMIT_ERROR')
        s = self.get_stream(sid, j)
        fs = f['final_size']
        if s.final_size is not None and fs != s.final_size:
            raise Err('FINAL_SIZE_ERROR')
        if fs < s.highest:
            raise Err('FINAL_SIZE_ERROR')
        if fs > self.max_stream_data:
            raise Err('FLOW_CONTROL_ERROR')
        nh = s.highest if s.highest > fs else fs
        if nh != s.highest and self.received_total + (nh - s.highest) > self.max_data:
            raise Err('FLOW_CONTROL_ERROR')
        if nh != s.highest:
            j.snap_total()
            self.received_total += nh - s.highest
            s.highest = nh
        s.final_size = fs
        s.reset = True

    def do_stop(self, f, j):
        sid = f['id']
        if (sid & 3) != 0:
            raise Err('STREAM_STATE_ERROR')
        if (sid >> 2) + 1 > self.max_streams_bidi:
            raise Err('STREAM_LIMIT_ERROR')
        s = self.get_stream(sid, j)
        s.stopped = True

    # -- output -----------------------------------------------------------

    def output(self, tid):
        packets = []
        for key in sorted(self.results.keys()):
            status, reason, at, frame = self.results[key]
            packets.append({'event': key[0], 'packet': key[1], 'status': status,
                            'reason': reason, 'at_ms': at, 'frame': frame})
        if self.term is None:
            conn = {'state': 'open', 'code': None, 'at_ms': None, 'source': None,
                    'peer_code': None, 'last_activity_ms': self.last_activity}
        else:
            state, code, at, source, peer = self.term
            conn = {'state': state, 'code': code, 'at_ms': at,
                    'source': {'event': source[0], 'packet': source[1], 'frame': source[2]},
                    'peer_code': peer, 'last_activity_ms': self.last_activity}
        streams = []
        for sid in sorted(self.streams.keys()):
            s = self.streams[sid]
            streams.append({'id': sid, 'highest': s.highest, 'final_size': s.final_size,
                            'reset': s.reset, 'stopped': s.stopped,
                            'delivered_hex': s.store.prefix().hex()})
        crypto = []
        for lv in ('I', 'H', 'A'):
            crypto.append({'level': lv, 'highest': self.crypto_high[lv],
                           'contiguous_hex': self.crypto[lv].prefix().hex()})
        return {'id': tid, 'packets': packets, 'connection': conn,
                'keys': {'I': self.keys['I'], 'H': self.keys['H'],
                         'Z': self.keys['Z'], 'A': self.keys['A']},
                'received_total': self.received_total,
                'streams': streams, 'crypto': crypto}


def run_trace(tr):
    st = State(tr['config'])
    events = tr['events']
    for e in range(len(events)):
        ev = events[e]
        t = ev['t']
        if st.term is None and st.idle_ms > 0 and t >= st.last_activity + st.idle_ms:
            st.terminate('idle', 'IDLE_TIMEOUT', st.last_activity + st.idle_ms,
                         (e, None, None), None)
        if st.term is not None:
            if ev['op'] == 'datagram':
                pkts = ev['packets']
                for p in range(len(pkts)):
                    st.record(e, p, S_DROP, 'CONNECTION_CLOSED', t, None)
            continue
        op = ev['op']
        if op == 'tick':
            continue
        if op == 'key':
            st.key_event(e, ev, t)
        else:
            st.datagram(e, ev, t)
    for r in st.pending:
        st.record(r[0], r[1], S_BUF, 'NO_KEYS', r[2], None)
    st.pending = []
    return st.output(tr['id'])


def main():
    data = sys.stdin.buffer.read()
    out = None
    try:
        if len(data) > 16 * 1024 * 1024:
            die()
        obj = parse_text(data)
        traces = validate(obj)
        results = [run_trace(tr) for tr in traces]
        out = {'version': 1, 'results': results}
    except Invalid:
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
        return
    except RecursionError:
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
        return
    except Exception:
        # Never crash: emit the invalid-input document instead.
        import traceback
        traceback.print_exc(file=sys.stderr)
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
        return
    sys.stdout.write(json.dumps(out, separators=(',', ':')))
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
