import json, subprocess, sys, os

def run(req):
    p = subprocess.run([sys.executable, '/app/submission/entry.py'], input=json.dumps(req).encode(),
                       capture_output=True, cwd='/app/submission')
    if p.returncode != 0:
        return {'__crash__': p.returncode, 'stderr': p.stderr.decode()[-2000:]}
    try:
        return json.loads(p.stdout.decode())
    except Exception as e:
        return {'__badout__': p.stdout.decode()[:500], 'err': str(e), 'stderr': p.stderr.decode()[-2000:]}

def cfg(**kw):
    d = dict(early=False, overlap='reject', buffer_packets=2, idle_ms=10,
             max_streams_bidi=4, max_streams_uni=4, max_stream_data=32, max_data=64,
             crypto_limit=32, sent={'I': [], 'H': [], 'A': []})
    d.update(kw)
    return d

def trace(tid, events, **kw):
    return {'id': tid, 'config': cfg(**kw), 'events': events}

def dg(t, packets, size=1200):
    return {'t': t, 'op': 'datagram', 'bytes': size, 'packets': packets}

def pkt(level, pn, frames, auth=True):
    return {'level': level, 'pn': pn, 'auth': auth, 'frames': frames}

def key(t, level, action):
    return {'t': t, 'op': 'key', 'level': level, 'action': action}

def tick(t):
    return {'t': t, 'op': 'tick'}

def F(**kw):
    return kw

def show(res, keys=('status','reason','at_ms','frame')):
    out = []
    for r in res['results']:
        out.append(r['id'])
        for p in r['packets']:
            out.append('  ev%d pk%d %s' % (p['event'], p['packet'], {k: p[k] for k in keys}))
        out.append('  conn=%s' % json.dumps(r['connection']))
        out.append('  keys=%s total=%d' % (r['keys'], r['received_total']))
        if r['streams']: out.append('  streams=%s' % json.dumps(r['streams']))
        if any(c['highest'] or c['contiguous_hex'] for c in r['crypto']): out.append('  crypto=%s' % json.dumps(r['crypto']))
    return '\n'.join(out)
