"""Naive reference implementation of the same contract (slow but simple)."""
import json, re, copy, bisect

MAXP = 4611686018427387903

class Err(Exception):
    def __init__(self, code, frame=None):
        self.code = code; self.frame = frame

def permitted(level, f):
    t = f['type']
    if t in ('PADDING','PING'): return True
    if t in ('ACK','CRYPTO'): return level != 'Z'
    if t in ('STREAM','RESET_STREAM','STOP_SENDING'): return level in ('Z','A')
    if t == 'CLOSE':
        return (level in ('Z','A')) if f['app'] else True
    return False

def covered(sent, lo, hi):
    for a,b in sent:
        if a <= lo and hi <= b: return True
        if a > lo: break
    return False

class Trace:
    def __init__(self, cfg):
        self.cfg = cfg
        self.keys = {'I':'live','H':'absent','Z':'live' if cfg['early'] else 'absent','A':'absent'}
        self.pn = {'I':set(),'H':set(),'A':set()}
        self.streams = {}   # sid -> dict
        self.crypto = {'I':{'high':0,'b':{}},'H':{'high':0,'b':{}},'A':{'high':0,'b':{}}}
        self.total = 0
        self.pending = []
        self.act = 0
        self.res = {}
        self.term = None

    def rec(self,e,p,st,reason,at,fr):
        assert (e,p) not in self.res, ('dup record',e,p)
        self.res[(e,p)] = (st,reason,at,fr)

    def term_now(self, state, code, at, src, peer):
        assert self.term is None
        self.term = (state, code, at, src, peer)
        for (e,p,t,lv,pkt) in self.pending:
            self.rec(e,p,'dropped','CONNECTION_CLOSED',at,None)
        self.pending = []

    def snapshot(self):
        return (copy.deepcopy(self.streams), copy.deepcopy(self.crypto), self.total)

    def restore(self, snap):
        self.streams, self.crypto, self.total = snap

    def getstream(self, sid):
        if sid not in self.streams:
            self.streams[sid] = {'highest':0,'final_size':None,'reset':False,'stopped':False,'b':{}}
        return self.streams[sid]

    def store_bytes(self, bdict, off, data, keep):
        for i,b in enumerate(data):
            o = off+i
            if o in bdict and keep: continue
            bdict[o] = b

    def conflict(self, bdict, off, data):
        for i,b in enumerate(data):
            o = off+i
            if o in bdict and bdict[o] != b: return True
        return False

    def prefix(self, bdict):
        out = bytearray(); i = 0
        while i in bdict:
            out.append(bdict[i]); i += 1
        return bytes(out)

    def process(self, e, p, pkt, t):
        lvl = pkt['level']; pn = pkt['pn']
        if not pkt['auth']:
            self.rec(e,p,'dropped','AUTH',t,None); return
        key = 'A' if lvl in ('Z','A') else lvl
        if pn in self.pn[key]:
            self.rec(e,p,'duplicate','DUPLICATE',t,None); return
        frames = pkt['frames']
        if not frames:
            self.term_now('closed','FRAME_ENCODING_ERROR',t,(e,p,None),None)
            self.rec(e,p,'error','FRAME_ENCODING_ERROR',t,None); return
        for i,f in enumerate(frames):
            if f['type'] == 'UNKNOWN':
                self.term_now('closed','FRAME_ENCODING_ERROR',t,(e,p,i),None)
                self.rec(e,p,'error','FRAME_ENCODING_ERROR',t,i); return
            if not permitted(lvl, f):
                self.term_now('closed','PROTOCOL_VIOLATION',t,(e,p,i),None)
                self.rec(e,p,'error','PROTOCOL_VIOLATION',t,i); return
        snap = self.snapshot()
        try:
            for i,f in enumerate(frames):
                ft = f['type']
                if ft in ('PADDING','PING'): continue
                if ft == 'ACK':
                    rs = f['ranges']
                    if not rs: raise Err('FRAME_ENCODING_ERROR', i)
                    prev = None
                    for r in rs:
                        if r[0] > r[1]: raise Err('FRAME_ENCODING_ERROR', i)
                        if prev is not None and r[0] <= prev+1: raise Err('FRAME_ENCODING_ERROR', i)
                        prev = r[1]
                    for r in rs:
                        if not covered(self.cfg['sent'][lvl], r[0], r[1]):
                            raise Err('PROTOCOL_VIOLATION', i)
                elif ft == 'CRYPTO':
                    data = bytes.fromhex(f['data_hex']); off = f['offset']
                    end = off + len(data)
                    if end > MAXP: raise Err('FRAME_ENCODING_ERROR', i)
                    if end > self.cfg['crypto_limit']: raise Err('CRYPTO_BUFFER_EXCEEDED', i)
                    c = self.crypto[lvl]
                    if self.cfg['overlap'] == 'reject' and self.conflict(c['b'], off, data):
                        raise Err('PROTOCOL_VIOLATION', i)
                    self.store_bytes(c['b'], off, data, self.cfg['overlap']=='first')
                    c['high'] = max(c['high'], end)
                elif ft == 'STREAM':
                    sid = f['id']; m = sid % 4
                    if m not in (0,2): raise Err('STREAM_STATE_ERROR', i)
                    limit = self.cfg['max_streams_bidi'] if m==0 else self.cfg['max_streams_uni']
                    if sid//4 + 1 > limit: raise Err('STREAM_LIMIT_ERROR', i)
                    s = self.getstream(sid)
                    data = bytes.fromhex(f['data_hex']); off = f['offset']; fin = f['fin']
                    end = off + len(data)
                    if end > MAXP: raise Err('FRAME_ENCODING_ERROR', i)
                    if s['final_size'] is not None and (end > s['final_size'] or (fin and end != s['final_size'])):
                        raise Err('FINAL_SIZE_ERROR', i)
                    if fin and end < s['highest']: raise Err('FINAL_SIZE_ERROR', i)
                    if end > self.cfg['max_stream_data']: raise Err('FLOW_CONTROL_ERROR', i)
                    nh = max(s['highest'], end)
                    if nh > s['highest'] and self.total + (nh - s['highest']) > self.cfg['max_data']:
                        raise Err('FLOW_CONTROL_ERROR', i)
                    if not s['reset']:
                        if self.cfg['overlap']=='reject' and self.conflict(s['b'], off, data):
                            raise Err('PROTOCOL_VIOLATION', i)
                        self.store_bytes(s['b'], off, data, self.cfg['overlap']=='first')
                    self.total += nh - s['highest']
                    s['highest'] = nh
                    if fin: s['final_size'] = end
                elif ft == 'RESET_STREAM':
                    sid = f['id']; m = sid % 4
                    if m not in (0,2): raise Err('STREAM_STATE_ERROR', i)
                    limit = self.cfg['max_streams_bidi'] if m==0 else self.cfg['max_streams_uni']
                    if sid//4 + 1 > limit: raise Err('STREAM_LIMIT_ERROR', i)
                    s = self.getstream(sid)
                    fs = f['final_size']
                    if s['final_size'] is not None and fs != s['final_size']: raise Err('FINAL_SIZE_ERROR', i)
                    if fs < s['highest']: raise Err('FINAL_SIZE_ERROR', i)
                    if fs > self.cfg['max_stream_data']: raise Err('FLOW_CONTROL_ERROR', i)
                    nh = max(s['highest'], fs)
                    if nh > s['highest'] and self.total + (nh - s['highest']) > self.cfg['max_data']:
                        raise Err('FLOW_CONTROL_ERROR', i)
                    self.total += nh - s['highest']
                    s['highest'] = nh
                    s['final_size'] = fs
                    s['reset'] = True
                elif ft == 'STOP_SENDING':
                    sid = f['id']
                    if sid % 4 != 0: raise Err('STREAM_STATE_ERROR', i)
                    if sid//4 + 1 > self.cfg['max_streams_bidi']: raise Err('STREAM_LIMIT_ERROR', i)
                    self.getstream(sid)['stopped'] = True
                else:  # CLOSE
                    app = f['app']
                    self.pn[key].add(pn); self.act = t
                    self.term_now('closed', 'PEER_APPLICATION_CLOSE' if app else 'PEER_TRANSPORT_CLOSE',
                                  t, (e,p,i), f['code'])
                    self.rec(e,p,'accepted','OK',t,None)
                    return
        except Err as ex:
            self.restore(snap)
            self.term_now('closed', ex.code, t, (e,p,ex.frame), None)
            self.rec(e,p,'error',ex.code,t,ex.frame)
            return
        self.pn[key].add(pn); self.act = t
        self.rec(e,p,'accepted','OK',t,None)

    def key_event(self, e, ev, t):
        lv = ev['level']; ac = ev['action']
        if ac == 'discard':
            if self.keys[lv] != 'discarded':
                self.keys[lv] = 'discarded'
                keep = []
                for r in self.pending:
                    if r[3] == lv: self.rec(r[0],r[1],'dropped','KEYS_DISCARDED',t,None)
                    else: keep.append(r)
                self.pending = keep
        else:
            if self.keys[lv] == 'absent':
                self.keys[lv] = 'live'
                drain = [r for r in self.pending if r[3]==lv]
                self.pending = [r for r in self.pending if r[3]!=lv]
                for r in drain:
                    if self.term is not None:
                        self.rec(r[0],r[1],'dropped','CONNECTION_CLOSED',self.term[2],None)
                    else:
                        self.process(r[0],r[1],r[4],t)

    def datagram(self, e, ev, t):
        pkts = ev['packets']; size = ev['bytes']
        if any(q['level']=='A' for q in pkts[:-1]):
            for p in range(len(pkts)): self.rec(e,p,'dropped','LAYOUT',t,None)
            return
        for p,pkt in enumerate(pkts):
            if self.term is not None:
                self.rec(e,p,'dropped','CONNECTION_CLOSED',t,None); continue
            lvl = pkt['level']
            if lvl=='I' and size < 1200:
                self.rec(e,p,'dropped','INITIAL_TOO_SMALL',t,None); continue
            if lvl=='Z' and not self.cfg['early']:
                self.rec(e,p,'dropped','EARLY_REJECTED',t,None); continue
            ks = self.keys[lvl]
            if ks=='discarded':
                self.rec(e,p,'dropped','KEYS_DISCARDED',t,None); continue
            if ks=='absent':
                if len(self.pending) < self.cfg['buffer_packets']:
                    self.pending.append((e,p,t,lvl,pkt))
                else:
                    self.rec(e,p,'dropped','BUFFER_FULL',t,None)
                continue
            self.process(e,p,pkt,t)

    def output(self, tid):
        packets = []
        for k in sorted(self.res.keys()):
            st,reason,at,fr = self.res[k]
            packets.append({'event':k[0],'packet':k[1],'status':st,'reason':reason,'at_ms':at,'frame':fr})
        if self.term is None:
            conn = {'state':'open','code':None,'at_ms':None,'source':None,'peer_code':None,'last_activity_ms':self.act}
        else:
            state,code,at,src,peer = self.term
            conn = {'state':state,'code':code,'at_ms':at,
                    'source':{'event':src[0],'packet':src[1],'frame':src[2]},'peer_code':peer,
                    'last_activity_ms':self.act}
        streams = [{'id':sid,'highest':s['highest'],'final_size':s['final_size'],'reset':s['reset'],
                    'stopped':s['stopped'],'delivered_hex':self.prefix(s['b']).hex()}
                   for sid,s in sorted(self.streams.items())]
        crypto = [{'level':lv,'highest':self.crypto[lv]['high'],'contiguous_hex':self.prefix(self.crypto[lv]['b']).hex()}
                  for lv in ('I','H','A')]
        return {'id':tid,'packets':packets,'connection':conn,
                'keys':dict(self.keys),'received_total':self.total,'streams':streams,'crypto':crypto}


def run(obj):
    out = []
    for tr in obj['traces']:
        t = Trace(tr['config'])
        for e,ev in enumerate(tr['events']):
            tt = ev['t']
            if t.term is None and tr['config']['idle_ms'] > 0 and tt >= t.act + tr['config']['idle_ms']:
                t.term_now('idle','IDLE_TIMEOUT', t.act + tr['config']['idle_ms'], (e,None,None), None)
            if t.term is not None:
                if ev['op'] == 'datagram':
                    for p in range(len(ev['packets'])):
                        t.rec(e,p,'dropped','CONNECTION_CLOSED',tt,None)
                continue
            if ev['op'] == 'key': t.key_event(e,ev,tt)
            elif ev['op'] == 'datagram': t.datagram(e,ev,tt)
        for (e,p,tt,lv,pkt) in t.pending:
            t.rec(e,p,'buffered','NO_KEYS',tt,None)
        out.append(t.output(tr['id']))
    return {'version':1,'results':out}
